  padding: 9px 10px;
  border-bottom: 1px solid var(--hw-hairline-grey);
  vertical-align: top;
}

.hw-about-source-table th {
  border-top: 1px solid var(--hw-primary-navy);
  border-bottom: 2px solid var(--hw-primary-navy);
  color: var(--hw-slate-label);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-align: left;
  text-transform: uppercase;
}

.hw-about-source-table td:first-child {
  color: var(--hw-primary-navy);
  font-weight: 700;
}

.hw-about-detail-stack {
  display: grid;
  gap: 0;
  margin-top: 18px;
}

.hw-about-detail {
  border-top: 1px solid var(--hw-hairline-grey);
  background: var(--hw-canvas-white);
}

.hw-about-detail:last-child {
  border-bottom: 1px solid var(--hw-hairline-grey);
}

.hw-about-detail summary {
  cursor: pointer;
  position: relative;
  padding: 13px 4px 13px 28px;
  color: var(--hw-primary-navy);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  list-style: none;
}

.hw-about-detail summary::-webkit-details-marker {
  display: none;
}

.hw-about-detail summary::before {
  content: ">";
  position: absolute;
  left: 8px;
  top: 13px;
  color: var(--hw-accent-orange);
  font-size: 0.82rem;
  font-weight: 700;
}

.hw-about-detail[open] summary::before {
  transform: rotate(90deg);
}

.hw-about-detail[open] summary {
  border-bottom: 0;
}

.hw-about-detail-body {
  padding: 0 4px 16px 28px;
}

.hw-about-assumption-table td:nth-child(2) {
  color: var(--hw-primary-navy);
  font-weight: 700;
}

.hw-about-closing-note {
  margin-top: 24px;
}

.hw-fiscal-kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.hw-person-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 16px;
}

.hw-person-kpi-grid-compact {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-bottom: 0;
}

.hw-model-tabs > .tabbable > .nav-tabs {
  position: absolute;
  top: -84px;
  left: 0;
  right: 150px;
  margin: 0;
  padding-left: 0;
  border-bottom: 0;
  z-index: 1;
}

.hw-model-tabs > .tabbable > .nav-tabs .nav-link {
  margin: 0 4px -1px 0;
  padding: 7px 13px 6px;
  border: 1px solid var(--hw-hairline-grey);
  border-bottom-color: var(--hw-hairline-grey);
  border-radius: 4px 4px 0 0;
  background: var(--hw-field-grey);
  color: var(--hw-slate-label);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.hw-model-tabs > .tabbable > .nav-tabs .nav-link.active {
  border-color: var(--hw-hairline-grey);
  border-bottom-color: var(--hw-canvas-white);
  color: var(--hw-primary-navy);
  background: var(--hw-canvas-white);
}

.hw-model-tabs > .tabbable > .tab-content {
  padding-top: 0;
}

.hw-export-results-button.btn {
  position: absolute;
  top: -85px;
  right: 0;
  z-index: 2;
  padding: 7px 12px 6px;
  border: 1px solid var(--hw-muted-orange-border);
  border-radius: 3px;
  background: var(--hw-input-cream);
  color: var(--hw-primary-navy);
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  line-height: 1.2;
  text-transform: uppercase;
  box-shadow: none;
}

.hw-export-results-button.btn:hover,
.hw-export-results-button.btn:focus {
  border-color: var(--hw-accent-orange);
  background: var(--hw-canvas-white);
  color: var(--hw-primary-navy);
  box-shadow: none;
}

.hw-chart-section,
.hw-summary-section {
  margin-bottom: 16px;
}

.hw-chart-section .shiny-plot-output {
  width: 100%;
}

.hw-grid-spacer {
  min-width: 0;
}

.hw-inline-radio .form-group {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 4px;
}

.hw-inline-radio .control-label {
  margin-bottom: 0;
}

.hw-inline-radio .shiny-options-group {
  display: flex;
  align-items: center;
  gap: 14px;
}

.hw-inline-radio .radio-inline {
  margin: 0;
}

.hw-inline-select .form-group {
  display: grid;
  grid-template-columns: auto minmax(260px, 1fr);
  align-items: center;
  gap: 12px;
  margin-bottom: 4px;
}

.hw-inline-select .control-label {
  margin-bottom: 0;
}

.hw-inline-select .shiny-input-container {
  width: 100%;
}

.hw-headline-section .hw-kpi-card {
  margin-bottom: 10px;
}

.hw-headline-section .hw-kpi-value {
  font-size: 1.65rem;
}

.hw-headline-metrics {
  margin-bottom: 10px;
}

.hw-kpi-card {
  margin-bottom: 14px;
  padding: 12px 14px;
  border: 1px solid var(--hw-hairline-grey);
  border-radius: 3px;
  background: var(--hw-canvas-white);
}

.hw-kpi-label {
  color: var(--hw-slate-label);
  font-size: 0.76rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.hw-kpi-value {
  margin-top: 4px;
  color: var(--hw-primary-navy);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.85rem;
  font-weight: 400;
  line-height: 1.1;
}

.hw-kpi-sub {
  margin-top: 4px;
  color: var(--hw-slate-label);
  font-size: 0.76rem;
  line-height: 1.3;
}

.hw-kpi-value-accent {
  color: var(--hw-accent-orange);
}

.table {
  margin-bottom: 0;
  color: var(--hw-body-navy);
  font-size: 0.9rem;
}

.table > tbody > tr > td {
  padding: 8px 4px;
  border-color: var(--hw-hairline-grey);
}

.table > tbody > tr > td:first-child {
  color: var(--hw-slate-label);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.table > tbody > tr > td:last-child {
  text-align: right;
  color: var(--hw-body-navy);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

.hw-note-section {
  margin-top: 6px;
  border-bottom-width: 1px;
}

.hw-note-section ul {
  margin: 0;
  padding-left: 20px;
}

.hw-note-section li {
  margin-bottom: 7px;
  color: var(--hw-body-navy);
  font-size: 0.88rem;
  line-height: 1.45;
}

.hw-note-section li:last-child {
  margin-bottom: 0;
}

.hw-note-section strong {
  color: var(--hw-slate-label);
  font-size: 0.78rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.hw-about-follow {
  margin-top: 10px;
}

.hw-panel-note {
  margin: 10px 0 0;
  color: var(--hw-slate-label);
  font-size: 0.78rem;
  line-height: 1.4;
}

.hw-note-with-info {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 10px;
}

.hw-note-with-info > .hw-panel-note {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
}

.hw-note-with-info > .hw-info-popover {
  flex: 0 0 auto;
}

@media (max-width: 1100px) {
  .hw-dashboard,
  .hw-fiscal-top-grid,
  .hw-offset-sensitivity-grid,
  .hw-two-chart-grid,
  .hw-cohort-transition-grid,
  .hw-about-grid,
  .hw-about-card-row,
  .hw-fiscal-kpi-grid,
  .hw-person-kpi-grid {
    grid-template-columns: 1fr;
  }

  .hw-page {
    padding: 22px 22px 26px;
  }

  .hw-title-logo {
    width: 44px;
    height: 48px;
  }

  .hw-header h1 {
    font-size: 1.72rem;
  }

  .hw-field-grid,
  .hw-reform-grid {
    grid-template-columns: 1fr;
  }

  .hw-model-tabs > .tabbable > .nav-tabs {
    position: static;
    margin-bottom: 14px;
    border-bottom: 1px solid var(--hw-hairline-grey);
  }

  .hw-export-results-button.btn {
    position: static;
    margin-bottom: 12px;
  }
}
